140	pub fn execute_extension(input: ExecuteExtensionInput) -> ExecuteExtensionOutput {
141	    use callisto_graph::commands::status::{status, StatusOptions};
142	
143	    // moon's real `ExecuteExtensionInput` nests the workspace root (and cwd)
144	    // inside `context: MoonContext` rather than as a flat `workspace_root`
145	    // field. `MoonContext::workspace_root` is a `VirtualPath`; `.to_path_buf()`
146	    // returns the (possibly WASI-virtualized) path, matching how the old flat
147	    // field was consumed below.
148	    let root = input.context.workspace_root.to_path_buf();
149	    let runner = crate::runner::MoonCommandRunner;
150	    let locator = match crate::locator::MoonProjectLocator::new(&runner, root.clone()) {
151	        Ok(loc) => loc,
152	        Err(e) => {
153	            let json_val = serde_json::json!({
154	                "schemaVersion": callisto_model::SCHEMA_VERSION,
155	                "error": { "code": "E_LOCATE", "message": e.to_string() }
156	            });
157	            return ExecuteExtensionOutput {
158	                report: json_val.clone(),
159	                rendered: e.to_string(),
160	                exit_code: 1,
161	            };
162	        }
163	    };
164	
165	    let ws = match callisto_graph::Workspace::load(root, &locator, &runner) {
166	        Ok(ws) => ws,
167	        Err(e) => {
168	            let json_val = format_graph_error_json(&e);
169	            return ExecuteExtensionOutput {
170	                report: json_val.clone(),
171	                rendered: e.to_string(),
172	                exit_code: 1,
173	            };
174	        }
175	    };
176	
177	    let subcmd = resolve_subcommand(&input.args);
178	
179	    match subcmd {
180	        "plan-publish" | "plan_publish" => {
181	            use callisto_graph::commands::publish::{plan_publish, PublishOptions};
182	            match plan_publish(&ws, &PublishOptions::default()) {
183	                Ok(report) => build_extension_output(serde_json::to_value(&report), 0),
184	                Err(e) => {
185	                    let json_val = format_graph_error_json(&e);
186	                    ExecuteExtensionOutput {
187	                        report: json_val.clone(),
188	                        rendered: e.to_string(),
189	                        exit_code: 1,
190	                    }
191	                }
192	            }
193	        }
194	        "validate" => {
195	            use callisto_graph::commands::validate::{validate, ValidateOptions};
196	            match validate(&ws, &ValidateOptions::default()) {
197	                Ok(report) => {
198	                    let exit_code = if report.ok { 0 } else { 1 };
199	                    build_extension_output(serde_json::to_value(&report), exit_code)
200	                }
201	                Err(e) => {
202	                    let json_val = format_graph_error_json(&e);
203	                    ExecuteExtensionOutput {
204	                        report: json_val.clone(),
205	                        rendered: e.to_string(),
206	                        exit_code: 1,
207	                    }
208	                }
209	            }
210	        }
211	        _ => {
212	            let opts = StatusOptions {
213	                strict: false,
214	                strict_graph: false,
215	            };
216	
217	            match status(&ws, &opts) {
218	                Ok(report) => {
219	                    let has_errors = report
220	                        .diagnostics
221	                        .iter()
222	                        .any(|d| d.severity == callisto_model::DiagnosticSeverity::Error);
223	                    let exit_code = if has_errors { 1 } else { 0 };
224	                    build_extension_output(serde_json::to_value(&report), exit_code)
225	                }
226	                Err(e) => {
227	                    let json_val = format_graph_error_json(&e);
228	                    ExecuteExtensionOutput {
229	                        report: json_val.clone(),
230	                        rendered: e.to_string(),
231	                        exit_code: 1,
232	                    }
233	                }
234	            }
235	        }
236	    }
237	}
