239	#[cfg(feature = "pdk")]
240	pub fn initialize_extension(input: InitializeExtensionInput) -> Result<InitializeExtensionOutput, LocateError> {
241	    use callisto_graph::commands::init::{init, InitOptions};
242	
243	    // moon's real `InitializeExtensionInput` (= `InitializePluginInput`) only
244	    // carries `context: MoonContext` — there is no `confirmed`/`yes` flag in
245	    // the real protocol (that was a callisto-only field on the old, locally
246	    // invented type). `InitOptions.yes` now gates `init`'s reconcile-apply
247	    // path (docs/00-design.md §18 Q5.4 mechanism 1): on a first run it has
248	    // no effect (scaffolding an absent `callisto.toml` is always a direct
249	    // write), and on a re-run it decides whether detected drift (e.g. a
250	    // newly-appeared ecosystem) is written or only reported. There is no
251	    // host-side prompt surface here to relay a diff through, so defaulting
252	    // to `true` — auto-applying reconcile drift — is the closest behavior-
253	    // preserving choice to the old unconditional-write behavior.
254	    let root = input.context.workspace_root.to_path_buf();
255	    let runner = crate::runner::MoonCommandRunner;
256	    let locator = crate::locator::MoonProjectLocator::new(&runner, root.clone())?;
257	    let ws = callisto_graph::Workspace::load(root, &locator, &runner).map_err(|e| LocateError::Graph(Box::new(e)))?;
258	    let opts = InitOptions { yes: true };
259	
260	    // Run callisto's existing init-detection/scaffolding logic. moon's real
261	    // `InitializeExtensionOutput` (= `InitializePluginOutput`) has no field
262	    // that can carry an arbitrary `InitReport` (schema version, config path,
263	    // diagnostics) — its shape is specifically for describing settings to
264	    // inject into moon's own toolchain config and prompts to ask the user,
265	    // neither of which callisto's `InitReport` maps onto cleanly. We still
266	    // run `init` for its side effects (scaffolding `callisto.toml` /
267	    // `.changeset`) and to propagate any error, but intentionally discard
268	    // the returned `InitReport` rather than inventing new output fields
269	    // moon doesn't expect. All fields below are therefore sensible defaults:
270	    // callisto has no hosted config/docs URL to advertise, no moon toolchain
271	    // settings to pre-populate, and no interactive prompts to ask.
272	    // This host surface has no `--dry-run` equivalent -- a moon extension
273	    // initialization is always a real scaffolding write -- so the permit is
274	    // granted unconditionally here rather than derived from a user flag. It
275	    // still goes through the one sanctioned constructor.
276	    let permit = callisto_model::ApplyPermit::granted_unless_dry_run(false);
277	    let _report = init(&ws, &opts, permit.as_ref()).map_err(|e| LocateError::Graph(Box::new(e)))?;
278	
279	    Ok(InitializeExtensionOutput {
280	        config_url: None,
281	        default_settings: Default::default(),
282	        docs_url: None,
283	        prompts: Vec::new(),
284	    })
285	}
