25	impl CargoToml {
26	    pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Self, ManifestError> {
27	        let rel_path = decl.path.clone();
28	        let abs_path = ctx.workspace_root.join(&rel_path);
29	
30	        let content = fs::read_to_string(&abs_path).map_err(|e| ManifestError::Read {
31	            path: rel_path.clone(),
32	            message: e.to_string(),
33	        })?;
34	
35	        let has_bom = content.starts_with('\u{FEFF}');
36	        let clean_content = content.strip_prefix('\u{FEFF}').unwrap_or(&content);
37	
38	        let doc: toml_edit::DocumentMut =
39	            clean_content
40	                .parse()
41	                .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
42	                    path: rel_path.clone(),
43	                    format: ManifestFormat::CargoToml,
44	                    message: e.to_string(),
45	                })?;
46	
47	        let inherited_version = doc
48	            .get("package")
49	            .and_then(|p| p.get("version"))
50	            .and_then(|v| v.get("workspace"))

50	            .and_then(|v| v.get("workspace"))
51	            .and_then(|w| w.as_bool())
52	            == Some(true);
53	
54	        let mut inherited_deps = HashSet::new();
55	        for (section_name, kind) in [
56	            ("dependencies", DepKind::Runtime),
57	            ("dev-dependencies", DepKind::Dev),
58	            ("build-dependencies", DepKind::Build),
59	        ] {
60	            if let Some(table) = doc.get(section_name).and_then(|t| t.as_table_like()) {
61	                for (name, item) in table.iter() {
62	                    let is_inherited = item
63	                        .as_inline_table()
64	                        .and_then(|t| t.get("workspace"))
65	                        .and_then(|w| w.as_bool())
66	                        == Some(true)
67	                        || item
68	                            .as_table()
69	                            .and_then(|t| t.get("workspace"))
70	                            .and_then(|w| w.as_bool())
71	                            == Some(true);
72	                    if is_inherited {
73	                        inherited_deps.insert((kind, name.to_string()));
74	                    }
75	                }
76	            }
77	        }
78	
79	        let uses_inheritance = inherited_version || !inherited_deps.is_empty();
80	        if uses_inheritance && ctx.cargo_workspace.is_none() {
81	            return Err(ManifestError::Read {
82	                path: rel_path,
83	                message: "declares .workspace = true but no WorkspaceCargoResolver context was supplied".to_string(),
84	            });
85	        }
86	
87	        Ok(CargoToml {
88	            path: rel_path,
89	            absolute: abs_path,
90	            workspace_root: ctx.workspace_root.to_path_buf(),
91	            role: decl.role.clone(),
92	            document: doc,
93	            inherited_deps,
94	            inherited_version,
95	            inheritance: ctx.cargo_workspace.clone(),
96	            has_bom,
97	        })
98	    }
99	}
