101	/// Extracts `[package].name` from an already-parsed `Cargo.toml` document.
102	/// Pure and I/O-free -- operates on a document the caller already has,
103	/// whether that's a fully-opened [`CargoToml`] (via [`Manifest::package_name`])
104	/// or a bare parse a caller made for some other purpose entirely (e.g.
105	/// `callisto-graph`'s `IdentityResolver`, which needs only a package name
106	/// and deliberately does not go through the full [`CargoToml::open`]
107	/// lifecycle -- that requires workspace-inheritance context this function
108	/// has no need for, since a package's *name* is never workspace-inherited).
109	pub fn cargo_package_name(doc: &toml_edit::DocumentMut) -> Option<&str> {
110	    doc.get("package").and_then(|p| p.get("name")).and_then(|n| n.as_str())
111	}
