114	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
115	        let mut text = self.document.to_string();
116	        if self.has_bom {
117	            text = format!("\u{FEFF}{}", text);
118	        }
119	        crate::atomic::atomic_write(&self.absolute, &text, permit).map_err(|e| ManifestError::Write {
120	            path: self.path.clone(),
121	            message: e.to_string(),
122	        })?;
123	        crate::record_persist_call();
124	        Ok(())
125	    }
