171	    fn current_version(&self) -> Result<Version, ManifestError> {
172	        if self.inherited_version {
173	            if let Some(ref inh) = self.inheritance {
174	                if let Some(ref v) = inh.version {
175	                    return Ok(v.clone());
176	                }
177	            }
178	            return Err(ManifestError::WorkspaceInherited {
179	                path: self.path.clone(),
180	                key: "version".to_string(),
181	            });
182	        }
183	
184	        let raw = self
185	            .document
186	            .get("package")
187	            .and_then(|p| p.get("version"))
188	            .and_then(|v| v.as_str())
189	            .ok_or_else(|| ManifestError::MissingField {
190	                path: self.path.clone(),
191	                field: "package.version",
192	            })?;
193	
194	        Version::parse(raw, VersionGrammar::SemVer).map_err(|source| ManifestError::InvalidVersion {
195	            path: self.path.clone(),
196	            raw: raw.to_string(),
