201	    fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
202	        if self.inherited_version {
203	            // The member uses `version.workspace = true` (or `version = { workspace = true }`).
204	            // Routing the bump to [workspace.package] would silently change the version for
205	            // every other workspace member. Instead, write an explicit pinned version directly
206	            // to this member's [package] section, replacing the workspace-inherited entry with
207	            // a standalone string value.
208	            let pkg = self
209	                .document
210	                .get_mut("package")
211	                .and_then(|p| p.as_table_mut())
212	                .ok_or_else(|| ManifestError::MissingField {
213	                    path: self.path.clone(),
214	                    field: "package",
215	                })?;
216	            pkg.insert("version", toml_edit::value(v.render()));
217	            self.inherited_version = false;
218	            return Ok(());
219	        }
220	
221	        let pkg = self
222	            .document
223	            .get_mut("package")
224	            .and_then(|p| p.as_table_mut())
225	            .ok_or_else(|| ManifestError::MissingField {
226	                path: self.path.clone(),
227	                field: "package",
228	            })?;
229	
230	        if let Some(item) = pkg.get_mut("version") {
231	            if let Some(val) = item.as_value_mut() {
232	                let decor = val.decor().clone();
233	                let mut new_val = toml_edit::Value::from(v.render());
234	                *new_val.decor_mut() = decor;
235	                *val = new_val;
236	            } else {
237	                pkg.insert("version", toml_edit::value(v.render()));
238	            }
239	        } else {
240	            pkg.insert("version", toml_edit::value(v.render()));
241	        }
242	        Ok(())
243	    }
