245	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
246	        let mut entries = Vec::new();
247	
248	        for (section_name, section_kind) in [
249	            ("dependencies", DepKind::Runtime),
250	            ("dev-dependencies", DepKind::Dev),
251	            ("build-dependencies", DepKind::Build),
252	        ] {
253	            if let Some(table) = self.document.get(section_name).and_then(|t| t.as_table_like()) {
254	                for (name, item) in table.iter() {
255	                    let is_inherited = self.inherited_deps.contains(&(section_kind, name.to_string()));
256	                    let mut kind = section_kind;
257	
258	                    let spec = if is_inherited {
259	                        if let Some(ref inh) = self.inheritance {
260	                            if let Some(inherited_dep) = inh.inherited(name) {
261	                                inherited_dep.spec.clone()
262	                            } else {
263	                                DepSpec::Opaque("workspace = true (unresolved)".to_string())
264	                            }
265	                        } else {
266	                            DepSpec::Opaque("workspace = true (unresolved)".to_string())
267	                        }
268	                    } else {
269	                        parse_cargo_dep_item(item, &mut kind)
270	                    };
271	
272	                    entries.push(DependencyEntry {
273	                        name: name.to_string(),
274	                        kind,
275	                        spec,
276	                        inherited: is_inherited,
277	                    });
278	                }
279	            }
280	        }
281	
282	        Box::new(entries.into_iter())
283	    }
