285	    fn update_dependency_spec(
286	        &mut self,
287	        name: &str,
288	        kind: DepKind,
289	        new: DepSpec,
290	        permit: &ApplyPermit,
291	    ) -> Result<(), ManifestError> {
292	        if kind == DepKind::Peer {
293	            return Err(ManifestError::DependencyNotFound {
294	                path: self.path.clone(),
295	                name: name.to_string(),
296	                kind,
297	            });
298	        }
299

299	
300	        if self.inherited_deps.contains(&(kind, name.to_string())) {
301	            let root_cargo = self.workspace_root.join("Cargo.toml");
302	            if self.absolute == root_cargo {
303	                return Err(ManifestError::InvariantViolation {
304	                    path: self.path.clone(),
305	                    message: format!(
306	                        "dependency `{name}` is workspace-inherited but this manifest IS the workspace root (`{}`); refusing to delegate to avoid overwriting the just-written root manifest with a stale in-memory document",
307	                        root_cargo.display()
308	                    ),
309	                });
310	            }
311	            let mut ws_res = WorkspaceCargoResolver::load(&root_cargo)?;
312	            return ws_res.write_dependency(name, new, permit);
313	        }
314	
315	        let section_name = match kind {
316	            DepKind::Runtime | DepKind::Optional => "dependencies",
317	            DepKind::Dev => "dev-dependencies",
318	            DepKind::Build => "build-dependencies",
319	            DepKind::Peer => unreachable!(),
320	        };
321	
322	        let table = self
323	            .document
324	            .get_mut(section_name)
325	            .and_then(|t| t.as_table_like_mut())
326	            .ok_or_else(|| ManifestError::DependencyNotFound {
327	                path: self.path.clone(),
328	                name: name.to_string(),
329	                kind,
330	            })?;
331	
332	        let item = table.get_mut(name).ok_or_else(|| ManifestError::DependencyNotFound {
333	            path: self.path.clone(),
334	            name: name.to_string(),
335	            kind,
336	        })?;
337	
338	        let new_str = new.render();
339	
340	        if let Some(value) = item.as_value_mut() {
341	            if value.is_str() {
342	                let decor = value.decor().clone();
343	                let mut new_val = toml_edit::Value::from(new_str);
344	                *new_val.decor_mut() = decor;
345	                *value = new_val;
346	            } else if let Some(inline) = value.as_inline_table_mut() {
347	                if let Some(existing_ver) = inline.get_mut("version") {
348	                    let decor = existing_ver.decor().clone();
349	                    let mut new_val = toml_edit::Value::from(new_str);
350	                    *new_val.decor_mut() = decor;
351	                    *existing_ver = new_val;
352	                } else {
353	                    inline.insert("version", toml_edit::Value::from(new_str));
354	                }
355	            } else {
356	                return Err(ManifestError::UnrecognizedDependencyValue {
357	                    path: self.path.clone(),
358	                    name: name.to_string(),
359	                });
360	            }
361	        } else if let Some(tbl) = item.as_table_mut() {
362	            let decor = tbl.get("version").and_then(|i| i.as_value()).map(|v| v.decor().clone());
363	            tbl.insert("version", toml_edit::value(new_str));
364	            if let Some(decor) = decor {
365	                if let Some(new_item) = tbl.get_mut("version").and_then(|i| i.as_value_mut()) {
366	                    *new_item.decor_mut() = decor;
367	                }
368	            }
369	        } else {
370	            return Err(ManifestError::UnrecognizedDependencyValue {
371	                path: self.path.clone(),
372	                name: name.to_string(),
373	            });
374	        }
375	
376	        Ok(())
377	    }
