392	fn parse_cargo_dep_item(item: &toml_edit::Item, kind: &mut DepKind) -> DepSpec {
393	    if let Some(table) = item.as_inline_table() {
394	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
395	            *kind = DepKind::Optional;
396	        }
397	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
398	            return parse_cargo_spec_str(v_str);
399	        }
400	    } else if let Some(table) = item.as_table() {
401	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
402	            *kind = DepKind::Optional;
403	        }
404	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
405	            return parse_cargo_spec_str(v_str);
406	        }
407	    } else if let Some(v_str) = item.as_str() {
408	        return parse_cargo_spec_str(v_str);
409	    }
410	
411	    DepSpec::Opaque(item.to_string().trim().to_string())
412	}
413	
414	fn parse_cargo_spec_str(s: &str) -> DepSpec {
415	    if crate::common::is_bare_semver(s) {
416	        if let Ok(v) = Version::parse(s, VersionGrammar::SemVer) {
417	            return DepSpec::CargoBare(v);
418	        }
419	    }
420	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Cargo) {
421	        return DepSpec::Range(req, s.to_string());
422	    }
423	    DepSpec::Opaque(s.to_string())
424	}
425	
426	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
427	    match spec {
428	        DepSpec::CargoBare(_) => Some(DepSpec::CargoBare(target.clone())),
429	        DepSpec::Range(_, original) => {
430	            if original.contains(',') {
431	                let parts: Vec<&str> = original.split(',').collect();
432	                let mut rewritten_parts = Vec::new();
433	                for part in parts {
434	                    let part_trimmed = part.trim();
435	                    let (prefix, rest) = crate::common::split_single_operator_prefix(part_trimmed)?;
436	                    if prefix.starts_with('>')
437	                        || prefix.starts_with('=')
438	                        || prefix.starts_with('^')
439	                        || prefix.starts_with('~')
440	                    {
441	                        let rendered = format!("{prefix}{}", render_at_precision(target, rest));
442	                        rewritten_parts.push(rendered);
443	                    } else if prefix.starts_with('<') {
444	                        // Upper-bound clauses are never rewritten (the clause text
445	                        // is preserved verbatim), but we must still check whether
446	                        // the target actually falls within it. If it doesn't, the
447	                        // rewrite would silently produce an impossible constraint
448	                        // (e.g. ">=2.1.0, <2.0.0"), so decline with None. If it
449	                        // does, the upper bound clause is passed through unchanged.
450	                        let bound = Version::parse(rest, target.grammar()).ok()?;
451	                        let ordering = target.partial_compare(&bound)?;
452	                        let exceeds_bound = if prefix == "<=" {
453	                            ordering == std::cmp::Ordering::Greater
454	                        } else {
455	                            ordering != std::cmp::Ordering::Less
456	                        };
457	                        if exceeds_bound {
458	                            return None;
459	                        }
460	                        rewritten_parts.push(part_trimmed.to_string());
461	                    } else {
462	                        rewritten_parts.push(part_trimmed.to_string());
463	                    }
464	                }
465	                let rendered = rewritten_parts.join(", ");
466	                let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
467	                return Some(DepSpec::Range(req, rendered));
468	            }
469	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
470	            if rest.contains('*') {
471	                return None;
472	            }
473	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
474	            let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
475	            Some(DepSpec::Range(req, rendered))
476	        }
477	        _ => None,
478	    }
479	}
480	
481	fn render_at_precision(target: &Version, original_clause: &str) -> String {
482	    if original_clause.contains('-') || target.is_prerelease() {
483	        return target.render().to_string();
484	    }
485	    let parts: Vec<&str> = original_clause.split('.').collect();
486	    let maj = target.major().unwrap_or(0);
487	    let min = target.minor().unwrap_or(0);
488	    let pat = target.patch().unwrap_or(0);
489	
490	    match parts.len() {
491	        1 => format!("{maj}"),
492	        2 => format!("{maj}.{min}"),
493	        _ => format!("{maj}.{min}.{pat}"),
494	    }
495	}
