526	impl WorkspaceCargoResolver {
527	    pub fn load(root_manifest_path: &Path) -> Result<Self, ManifestError> {
528	        let rel_path = if root_manifest_path.is_absolute() {
529	            root_manifest_path
530	                .file_name()
531	                .map(PathBuf::from)
532	                .unwrap_or_else(|| PathBuf::from("Cargo.toml"))
533	        } else {
534	            workspace_relative(root_manifest_path).map_err(|e| ManifestError::Read {
535	                path: root_manifest_path.to_path_buf(),
536	                message: e.to_string(),
537	            })?
538	        };
539	        let content = fs::read_to_string(root_manifest_path).map_err(|e| ManifestError::Read {
540	            path: rel_path.clone(),
541	            message: e.to_string(),
542	        })?;
543	
544	        let doc: toml_edit::DocumentMut = content
545	            .parse()
546	            .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
547	                path: rel_path.clone(),
548	                format: ManifestFormat::CargoToml,
549	                message: e.to_string(),
550	            })?;
551	
552	        Ok(WorkspaceCargoResolver {
553	            root_path: rel_path,
554	            absolute_path: root_manifest_path.to_path_buf(),
555	            document: doc,
556	        })
557	    }
558	
559	    pub fn inheritance(&self) -> Result<WorkspaceInheritance, ManifestError> {
560	        let version = self
561	            .document
562	            .get("workspace")
563	            .and_then(|w| w.get("package"))
564	            .and_then(|p| p.get("version"))
565	            .and_then(|v| v.as_str())
566	            .and_then(|s| Version::parse(s, VersionGrammar::SemVer).ok());
567	
568	        let mut dependencies = BTreeMap::new();
569	        if let Some(table) = self
570	            .document
571	            .get("workspace")
572	            .and_then(|w| w.get("dependencies"))
573	            .and_then(|d| d.as_table_like())
574	        {
575	            for (name, item) in table.iter() {
576	                let mut dummy_kind = DepKind::Runtime;
577	                let spec = parse_cargo_dep_item(item, &mut dummy_kind);
578	                dependencies.insert(name.to_string(), spec);
579	            }
580	        }
581	
582	        Ok(WorkspaceInheritance {
583	            root_manifest: self.root_path.clone(),
584	            version,
585	            dependencies,
586	        })
587	    }
588	
589	    /// Returns the `[workspace.package] version` currently on disk, or `None`
590	    /// when no such field exists (e.g. the workspace does not declare a shared
591	    /// version). Used by `apply_version_plan`'s idempotency guard.
592	    pub fn workspace_version(&self) -> Result<Option<Version>, ManifestError> {
593	        let raw = match self
594	            .document
595	            .get("workspace")
596	            .and_then(|w| w.get("package"))
597	            .and_then(|p| p.get("version"))
598	            .and_then(|v| v.as_str())
599	        {
600	            Some(s) => s,
601	            None => return Ok(None),
602	        };
