/// `round_trip`'s comma-joined multi-clause logic: an upper-bound
/// clause (`<`/`<=`) is preserved verbatim when the target version
/// still satisfies it, and the whole rewrite is declined (`None`) when
/// the target would violate it -- preventing a silently self-
/// contradictory range like `">=2.1.0, <2.0.0"`.
#[test]
fn round_trip_comma_joined_range_preserves_satisfied_upper_bound_and_declines_violated_one() {
    let req = VersionReq::parse(">=1.0.0, <2.0.0", Ecosystem::Cargo).unwrap();
    let spec = DepSpec::Range(req, ">=1.0.0, <2.0.0".to_string());

    // Target still satisfies the upper bound: rewritten, bound preserved verbatim.
    let target = Version::parse("1.5.0", VersionGrammar::SemVer).unwrap();
    let result = round_trip(&spec, &target).expect("upper bound satisfied, must rewrite");
    match result {
        DepSpec::Range(_, rendered) => {
            assert_eq!(rendered, ">=1.5.0, <2.0.0", "lower bound rewritten, upper bound preserved verbatim");
        }
        other => panic!("expected DepSpec::Range, got {other:?}"),
    }

    // Target violates the upper bound: the rewrite is declined outright.
    let target = Version::parse("2.5.0", VersionGrammar::SemVer).unwrap();
    assert_eq!(
        round_trip(&spec, &target),
        None,
        "must decline (None) rather than produce an impossible range like '>=2.5.0, <2.0.0'"
    );
}

