132	fn is_valid_git_ref_name(s: &str) -> bool {
133	    if s.is_empty() || s.starts_with('/') || s.ends_with('/') || s.contains("//") || s == "@" {
134	        return false;
135	    }
136	    // Git ref names may legally start with `-`, but every caller in this
137	    // codebase passes the rendered name as a bare positional to `git tag`
138	    // (or an equivalent CLI), whose argument parser treats a leading `-`
139	    // as an option rather than a ref name -- reject it here so a malicious
140	    // or accidental `tag-template` can never produce one.
141	    if s.starts_with('-') {
