40	/// Checks whether the environment has credentials for each ecosystem in
41	/// the plan. Returns human-readable warnings for any missing credentials
42	/// so the operator can spot auth problems before publishing; empty when
43	/// all required credentials are present.
44	///
45	/// `env` is injectable (pass [`std::env::var`] in production; a closure
46	/// in tests to avoid mutating the process environment).
47	///
48	/// Soft pre-flight check only -- doesn't fail hard. Missing credentials
49	/// may still let publish succeed via an alternative auth mechanism (a
50	/// pre-configured `.npmrc` or `~/.cargo/credentials`).
51	fn check_credentials(
52	    plan: &callisto_model::PublishPlan,
53	    env: impl Fn(&str) -> Result<String, std::env::VarError>,
54	) -> Vec<String> {
55	    let mut warnings = Vec::new();
56	
57	    // Cargo: crates targeting the default crates.io registry need
58	    // CARGO_REGISTRY_TOKEN; crates targeting a named private registry need
59	    // CARGO_REGISTRIES_<UPPERCASE_NAME>_TOKEN. Collect the distinct variable
60	    // names required and warn once per missing variable.
61	    let mut cargo_vars_checked = std::collections::BTreeSet::new();
62	    for pkg in &plan.rust_crates {
63	        let var = match &pkg.registry {
64	            None => "CARGO_REGISTRY_TOKEN".to_string(),
65	            Some(name) => format!("CARGO_REGISTRIES_{}_TOKEN", name.to_uppercase().replace('-', "_")),
66	        };
67	        if cargo_vars_checked.insert(var.clone()) && env(&var).is_err() {
68	            warnings.push(format!(
69	                "warning: {var} is not set; cargo publish may fail authentication"
70	            ));
71	        }
72	    }
73	
74	    if (!plan.npm_main_packages.is_empty() || !plan.npm_platform_packages.is_empty()) && env("NPM_TOKEN").is_err() {
75	        warnings.push("warning: NPM_TOKEN is not set; npm publish may fail authentication".to_string());
76	    }
77	
78	    if !plan.pypi_packages.is_empty() && env("TWINE_PASSWORD").is_err() {
79	        warnings.push("warning: TWINE_PASSWORD is not set; twine upload may fail authentication".to_string());
80	    }
81	
82	    warnings
83	}
