85	/// Publishes every package in the workspace's publish plan to its ecosystem
86	/// registry (crates.io, npm, PyPI) by shelling out to that ecosystem's own
87	/// publisher CLI (`cargo publish`, `npm publish`, `twine upload`) — never by
88	/// talking to a registry's HTTP API directly.
89	///
90	/// Respects the global `--dry-run` flag: when set, this only computes and
91	/// prints the plan that WOULD be published (the same plan `plan-publish`
92	/// reports) and returns without constructing a [`PublishOrchestrator`] or
93	/// running any publisher command.
94	pub fn handle(args: PublishArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
95	    let runner = CliCommandRunner;
96	    let ws = load_workspace(global, &runner)?;
97	
98	    let opts = PublishOptions { only: args.only };
99	    let plan = plan_publish(&ws, &opts)?;
100	
101	    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
102	        match global.format {
103	            OutputFormat::Json => write_report_json(&mut std::io::stdout(), &plan)?,
104	            OutputFormat::Text => write_dry_run_text(&plan, &mut std::io::stdout())?,
105	        }
106	        return Ok(ExitCode::SUCCESS);
107	    };
108	
109	    // Pre-flight credential check — warns before any packages are published so
110	    // the operator can identify missing auth tokens early.
111	    for warning in check_credentials(&plan, |s| std::env::var(s)) {
112	        eprintln!("{warning}");
113	    }
114	
115	    let mut client = SubprocessRegistryClient::new(CliCommandRunner, ws.root.clone());
116	    client.load_plan(&plan);
117	    let format = global.format;
118	    let orchestrator =
119	        PublishOrchestrator::new(client, AlwaysRetryPolicy, SystemTimeProvider).with_progress(move |msg| {
120	            crate::output::log_line(format, &msg);
121	        });
122	    let report = orchestrator.execute(&plan, &permit);
123	
124	    match global.format {
125	        OutputFormat::Json => write_report_json(&mut std::io::stdout(), &report)?,
126	        OutputFormat::Text => render::render_publish_report(&report, &mut std::io::stdout())?,
127	    }
128	
129	    if report.has_failures() {
130	        return Ok(ExitCode::FAILURE);
131	    }
132	
133	    Ok(ExitCode::SUCCESS)
134	}
