struct MockTimeProvider {
    time: Mutex<SystemTime>,
}

impl TimeProvider for MockTimeProvider {
    fn now(&self) -> SystemTime {
        *self.time.lock().unwrap()
    }

    fn sleep(&self, duration: Duration) {
        let mut time = self.time.lock().unwrap();
        *time += duration;
    }
}

