export const meta = {
  name: 'publish-pipeline-adversarial-audit',
  description: 'Multi-dimension adversarial audit of the publish pipeline (bugs, perf, corner/error cases, DX, security) with skeptic verification',
  phases: [
    { title: 'Recon', detail: 'map the real current surface area' },
    { title: 'Find', detail: 'five parallel dimension-finders' },
    { title: 'Verify', detail: 'adversarial refutation per finding' },
    { title: 'Synthesize', detail: 'grouped, deduped, severity-ranked report' },
  ],
}

const TARGET_FILES = [
  'crates/callisto-graph/src/commands/publish.rs',
  'crates/callisto-graph/src/commands/publish_client.rs',
  '.github/actions/setup-callisto/action.yml',
  '.github/actions/callisto-action/action.yml',
]

phase('Recon')
const recon = await agent(
  `Read these files in full and produce a structured map for an adversarial audit: /Users/gabe/Projects/callisto/${TARGET_FILES.join(', /Users/gabe/Projects/callisto/')}

Also read crates/callisto-model/src/plan.rs, crates/callisto-model/src/registry.rs, and crates/callisto-model/src/report.rs for the types these files construct/consume (PublishPlan, ReleaseEntry, PublishReport, PublishAttemptResult, RegistryError, NpmMainPublish/NpmPublish/CratePublish/PypiPublish).

Context: this is the package-publish orchestration pipeline (Rust side: PublishOrchestrator::execute in publish.rs, the ecosystem-specific RegistryClient impls in publish_client.rs) plus the two GitHub Action scripts that wrap it (setup-callisto installs the callisto binary via a 3-tier fallback chain including a crates.io install added this session; callisto-action runs version/publish/release-entry-creation and a native-artifact placement loop). A real bug was just found and fixed in publish.rs: depends_on_platforms comparison didn't scope by ecosystem, causing a same-named Cargo crate failure to false-positive-block an unrelated npm package. That class of bug (ecosystem/identity confusion, silent skip logic, retry/error-path edge cases) is exactly what this audit should hunt for more of.

Output: for each target file, a list of every function/shell-step with a one-line purpose, and explicitly flag: (a) every place two values from different "spaces" (ecosystems, package identities, error kinds, shell variables) get compared or merged, (b) every retry/loop/early-return/skip decision, (c) every place a shell script's exit code or error output could be silently swallowed (grep for || true, 2>/dev/null, unquoted variables). Return this as a structured manifest, not prose analysis -- analysis is the next phase's job.`,
  { phase: 'Recon', effort: 'high' }
)

phase('Find')
const DIMENSIONS = [
  {
    key: 'correctness',
    label: 'Bugs & Correctness',
    prompt: `Adversarially hunt for correctness bugs in the callisto publish pipeline (Rust: crates/callisto-graph/src/commands/publish.rs, publish_client.rs; shell: .github/actions/setup-callisto/action.yml, .github/actions/callisto-action/action.yml), workspace root /Users/gabe/Projects/callisto. Use this recon manifest as your map, but read the actual files yourself before reporting anything: ${JSON.stringify(recon).slice(0, 4000)}

Focus especially on: (1) identity/ecosystem confusion (comparing bare names, PackageIds, or error kinds across ecosystem/type boundaries without qualification -- exactly the class of bug already found once in this file), (2) retry logic correctness (does a retry actually retry the right thing, could it loop forever or give up too early, are error kinds classified correctly), (3) ordering/sequencing assumptions that could be violated by a real plan shape, (4) shell script quoting/variable-scoping bugs, (5) off-by-one or empty-collection edge cases. For each finding: exact file:line, the concrete failure scenario (not hypothetical), and a suggested fix. Do not report style preferences or things that are already correct -- only real, demonstrable defects.`,
  },
  {
    key: 'performance',
    label: 'Performance',
    prompt: `Hunt for real performance problems in the callisto publish pipeline (crates/callisto-graph/src/commands/publish.rs, publish_client.rs, .github/actions/setup-callisto/action.yml, .github/actions/callisto-action/action.yml), workspace root /Users/gabe/Projects/callisto. Read the actual files. Look for: redundant subprocess spawns, redundant network/registry calls (e.g. an is_published check followed by a publish call that duplicates work), O(n^2) patterns over packages/attempts, unnecessary allocations in hot loops, shell script steps that could be batched instead of looping. For each finding: exact file:line, why it's actually slow (not just theoretically), and estimated impact (e.g. "N extra subprocess spawns per N packages"). Skip anything below real, measurable impact -- no micro-optimization bikeshedding.`,
  },
  {
    key: 'corner-cases',
    label: 'Corner Cases & Error Handling',
    prompt: `Hunt for missed corner cases and error-handling gaps in the callisto publish pipeline (crates/callisto-graph/src/commands/publish.rs, publish_client.rs, .github/actions/setup-callisto/action.yml, .github/actions/callisto-action/action.yml), workspace root /Users/gabe/Projects/callisto. Read the actual files. Look for: empty-plan/empty-list cases, a package appearing in multiple ecosystem lists, a main package depending on a platform package that was never even in the plan (typo in depends_on_platforms), partial/interrupted runs, what happens if the SAME package name+version is attempted twice in one run, malformed or missing fields in a hand-constructed PublishPlan JSON consumed by the shell scripts. For each finding: exact file:line, the concrete scenario that triggers it, and what currently happens vs. what should happen. Only report cases that are actually reachable through the real public API/CLI, not internal states nothing can construct.`,
  },
  {
    key: 'dx',
    label: 'Developer Experience',
    prompt: `Review the callisto publish pipeline (crates/callisto-graph/src/commands/publish.rs, publish_client.rs, .github/actions/setup-callisto/action.yml, .github/actions/callisto-action/action.yml), workspace root /Users/gabe/Projects/callisto, for real developer-experience gaps: error messages that don't give an operator enough to act on, diagnostics that should exist but don't (e.g. warning when depends_on_platforms references a package not in the plan at all), confusing or misleading log output, missing documentation on non-obvious behavior (like the new dependencyFailed skip). Read the actual files. For each finding: exact file:line, what a real operator would experience, and a concrete improvement. Skip generic "add more comments" suggestions -- only report things that would actually confuse or mislead someone debugging a real failed release.`,
  },
  {
    key: 'security',
    label: 'Security',
    prompt: `Adversarially audit the callisto publish pipeline (crates/callisto-graph/src/commands/publish.rs, publish_client.rs, .github/actions/setup-callisto/action.yml, .github/actions/callisto-action/action.yml), workspace root /Users/gabe/Projects/callisto, for security issues. This pipeline runs with real registry credentials (NPM_TOKEN, CARGO_REGISTRY_TOKEN, GH_TOKEN) in CI. Read the actual files. Look for: credential/token leakage into logs or error messages, shell injection via unquoted/unsanitized variables (especially values that flow from a PublishPlan JSON an operator's own config partially controls, or from package names/paths), unvalidated URLs or paths reaching a subprocess call, the new crates.io/cargo-install fallback logic specifically (does an attacker-controlled version string reach a shell command unsanitized?). For each finding: exact file:line, the concrete attack scenario, and severity. Only report realistically exploitable issues, not theoretical hardening.`,
  },
]

const findings = await parallel(
  DIMENSIONS.map(d => () =>
    agent(d.prompt, {
      label: `find:${d.key}`,
      phase: 'Find',
      effort: 'high',
      schema: {
        type: 'object',
        properties: {
          findings: {
            type: 'array',
            items: {
              type: 'object',
              properties: {
                title: { type: 'string' },
                file: { type: 'string' },
                line: { type: 'string' },
                severity: { type: 'string', enum: ['critical', 'high', 'medium', 'low'] },
                scenario: { type: 'string' },
                fix: { type: 'string' },
              },
              required: ['title', 'file', 'scenario', 'fix', 'severity'],
            },
          },
        },
        required: ['findings'],
      },
    }).then(r => (r?.findings || []).map(f => ({ ...f, dimension: d.key })))
  )
)

const allFindings = findings.filter(Boolean).flat()
log(`${allFindings.length} raw findings across ${DIMENSIONS.length} dimensions`)

if (allFindings.length === 0) {
  return { verified: [], summary: 'No findings surfaced by any dimension.' }
}

phase('Verify')
const verified = await parallel(
  allFindings.map(f => () =>
    parallel(
      ['skeptic-1', 'skeptic-2'].map(() => () =>
        agent(
          `Adversarially try to REFUTE this audit finding against the real code at /Users/gabe/Projects/callisto. Read the actual file yourself -- do not trust the finding's own description. Default to refuted=true if you cannot find concrete evidence in the current code that this is a real, reachable, demonstrable defect (not a hypothetical or already-guarded case).

Finding: "${f.title}" (dimension: ${f.dimension}, claimed severity: ${f.severity})
Location: ${f.file}${f.line ? ':' + f.line : ''}
Claimed scenario: ${f.scenario}
Suggested fix: ${f.fix}

Report: refuted (bool), reasoning (what you actually checked in the code), and if not refuted, confirm the exact current file:line evidence.`,
          {
            phase: 'Verify',
            effort: 'high',
            schema: {
              type: 'object',
              properties: {
                refuted: { type: 'boolean' },
                reasoning: { type: 'string' },
              },
              required: ['refuted', 'reasoning'],
            },
          }
        )
      )
    ).then(votes => {
      const validVotes = votes.filter(Boolean)
      const refutedCount = validVotes.filter(v => v.refuted).length
      const survives = validVotes.length > 0 && refutedCount < validVotes.length / 2 + 0.5 * (validVotes.length % 2 === 0 ? 1 : 0) && refutedCount === 0
      return { ...f, survives, refutedCount, voteCount: validVotes.length, votes: validVotes }
    })
  )
)

const confirmed = verified.filter(v => v.survives)
const refuted = verified.filter(v => !v.survives)
log(`${confirmed.length}/${verified.length} findings survived adversarial verification`)

return {
  confirmed: confirmed.map(({ votes, ...rest }) => rest),
  refuted_count: refuted.length,
  refuted_titles: refuted.map(r => r.title),
}

export const meta = {
  name: 'publish-pipeline-fix-plan',
  description: 'Triple-verify the 18 confirmed publish-pipeline findings, cluster by interaction/root-cause, design fixes considering architecture/perf/semantics, adversarially challenge the combined plan, synthesize final ordered plan',
  phases: [
    { title: 'Triple-Verify' },
    { title: 'Cluster' },
    { title: 'Design' },
    { title: 'Challenge' },
    { title: 'Synthesize' },
  ],
}

const WORKSPACE = '/Users/gabe/Projects/callisto'

const FINDINGS = [
  { id: 'F1', severity: 'critical', title: 'git push origin --tags --force clobbers immutable release tags, not just the floating-major alias', file: '.github/actions/callisto-action/action.yml', line: '208-211' },
  { id: 'F2', severity: 'high', title: "publish_order's Dev-cycle fallback silently drops Dev-edge publish ordering for the whole plan, not just the cyclic pair", file: 'crates/callisto-graph/src/commands/publish.rs', line: '58-60' },
