  { id: 'F7', severity: 'medium', title: 'Native artifact placement loop: one gh run download subprocess per platform target, run fully sequentially, plus 2 jq spawns per entry that could be 1', file: '.github/actions/callisto-action/action.yml:168-179' },
  { id: 'F8', severity: 'low', title: 'GitHub Release creation loop spawns 3 separate jq processes per release entry instead of 1', file: '.github/actions/callisto-action/action.yml:215-232' },
  { id: 'F9', severity: 'high', title: 'Empty publish plan is reported as published=true', file: '.github/actions/callisto-action/action.yml:163-206' },
  { id: 'F10', severity: 'high', title: 'A single package publish failure aborts the step before tagging/releasing any of its successfully-published siblings', file: '.github/actions/callisto-action/action.yml:80,193-201,208-234' },
  { id: 'F11', severity: 'high', title: "--package/only filtering doesn't cascade to depends_on_platforms, letting a main npm package publish while depending on a platform package that isn't even in the plan", file: 'crates/callisto-graph/src/commands/publish.rs:463-489,545-570,700-726' },
  { id: 'F12', severity: 'critical', title: 'depends_on_platforms is never validated against what actually ends up in the plan — a broken npm release ships with zero diagnostics', file: 'crates/callisto-graph/src/commands/publish.rs:463-477,715-743' },
  { id: 'F13', severity: 'high', title: 'UnknownPackage error for --package <name> collapses three different real causes into one misleading message pointing at workspace membership', file: 'crates/callisto-graph/src/commands/publish.rs:563-569' },
  { id: 'F14', severity: 'medium', title: 'docs/06-publishing.md documents registry auth exhaustively but says nothing about the npm platform/main split, depends_on_platforms, or the dependencyFailed skip', file: 'docs/06-publishing.md' },
  { id: 'F15', severity: 'high', title: "callisto-action's tagging step swallows failures with || true, emits zero per-tag log output, then unconditionally force-pushes all tags", file: '.github/actions/callisto-action/action.yml:208-211' },
  { id: 'F16', severity: 'high', title: 'Credential redaction only covers the returned error string, never the live stderr stream that CI logs actually persist', file: 'crates/callisto-graph/src/commands/publish_client.rs:652-654,690-694,717-721,758-762 + crates/callisto-cli/src/runner.rs:52-59,182,206' },
