const stillConfirmed = verified.filter(v => v.triple_check_survives)
const nowRefuted = verified.filter(v => !v.triple_check_survives)
log(`${stillConfirmed.length}/${verified.length} findings survived a third independent round; ${nowRefuted.length} newly refuted`)

phase('Cluster')
