            type: 'object',
            properties: {
              cluster_id: { type: 'string' },
              name: { type: 'string' },
              finding_ids: { type: 'array', items: { type: 'string' } },
              grouping_reason: { type: 'string' },
            },
            required: ['cluster_id', 'name', 'finding_ids', 'grouping_reason'],
