log(`clustered into ${clusterPlan.clusters.length} groups`)

phase('Design')
const designs = await pipeline(
  clusterPlan.clusters,
  cluster => {
    const members = stillConfirmed.filter(f => cluster.finding_ids.includes(f.id))
    return agent(
      `Design a fix for this cluster of verified defects in callisto's publish pipeline (repo: ${WORKSPACE}). Read the actual current code at every referenced location yourself before designing anything -- do not design against the finding description alone.

Cluster: ${cluster.name}
Grouping reason: ${cluster.grouping_reason}
Findings in this cluster:
${JSON.stringify(members, null, 2)}

Think through, explicitly, in your reasoning before answering:
- Architecture: does this fix belong in the Rust core (callisto-graph/callisto-cli, testable, versioned, reusable) or in the shell/YAML orchestration layer? Prefer pushing logic into Rust with test coverage over growing bash, unless the finding is inherently a CI-orchestration concern.
