            approach: { type: 'string' },
            files_changed: { type: 'array', items: { type: 'string' } },
            new_tests: { type: 'array', items: { type: 'string' } },
            semantic_model_impact: { type: 'string' },
            performance_impact: { type: 'string' },
            interactions_and_risks: { type: 'string' },
            doc_spec_updates: { type: 'array', items: { type: 'string' } },
            estimated_risk: { type: 'string', enum: ['low', 'medium', 'high'] },
          },
          required: ['cluster_id', 'approach', 'files_changed', 'new_tests', 'semantic_model_impact', 'performance_impact', 'interactions_and_risks', 'estimated_risk'],
        },
      }
    )
  }
)

phase('Challenge')
const challenge = await agent(
  `You are adversarially reviewing a combined fix plan for callisto's publish pipeline (repo: ${WORKSPACE}) before any code is written. Below are the per-cluster designs. Read the actual current code yourself where needed to check claims.

Cluster designs:
${JSON.stringify(designs.filter(Boolean), null, 2)}

Cluster interaction notes from the clustering pass:
${JSON.stringify(clusterPlan.dependency_notes || [], null, 2)}

Challenge this plan on:
