/// cycle, this excludes `Dev` edges, but only between the specific packages
/// that form a Dev-induced cycle — a `Dev` edge anywhere else in `subset`
/// (e.g. an unrelated pair with no cycle at all) still counts, so one
/// legitimate Dev-only cycle can never silently un-order an unrelated
/// dev-dependency elsewhere in the same batch. A cycle that survives with
/// `Dev` edges excluded entirely is a genuine `Runtime`/`Build`/`Optional`
/// cycle and still hard-fails the whole plan, exactly as before.
fn publish_order<D: DependencyResolver + ?Sized>(
    resolver: &D,
    subset: &HashSet<PackageId>,
) -> Result<Vec<PackageId>, GraphError> {
    let all_pkg_ids: Vec<PackageId> = resolver.packages().map(|p| p.id.clone()).collect();
    let edges_of = |id: &PackageId| -> Vec<(PackageId, DepKind)> {
        resolver.dependencies_of(id).map(|e| (e.to.clone(), e.kind)).collect()
    };

    match toposort_impl(subset, &all_pkg_ids, PUBLISH_ORDERING_KINDS, edges_of) {
        Ok(order) => Ok(order),
        Err(GraphError::Cycle { .. }) => {
            // Confirm the cycle is Dev-induced: a cycle that survives without
            // any Dev edges at all is a genuine Runtime/Build/Optional cycle,
            // which must still hard-fail the whole plan.
            toposort_impl(subset, &all_pkg_ids, CASCADE_ORDERING_KINDS, edges_of)?;

            let cyclic_components =
                crate::toposort::cyclic_sccs(subset, edges_of, PUBLISH_ORDERING_KINDS);
            crate::toposort::toposort_with_edge_filter(subset, &all_pkg_ids, edges_of, |from, to, kind| {
                if !PUBLISH_ORDERING_KINDS.contains(&kind) {
                    return false;
                }
                if kind == DepKind::Dev {
                    let in_same_cyclic_component =
                        cyclic_components.iter().any(|scc| scc.contains(from) && scc.contains(to));
                    return !in_same_cyclic_component;
                }
                true
            })
        }
        Err(e) => Err(e),
    }
}

