{
  "id": "SPEC-RELEASE-SOURCE-PROVENANCE-002",
  "purpose": "Bind release intent, release tags, and publish reports to one immutable source commit while keeping the core release engine independent of GitHub or any particular signing service.",
  "scope": "Source-commit representation in release plans and reports; commit and tag resolution before mutation; provider-neutral provenance policy; clear diagnostics for mismatch. Forge-specific authorization and attestation integration are adapters.",
  "non_goals": [
    "Mandating GPG, SSH, Sigstore, GitHub, GitLab, Bazel, or any other forge or signing provider.",
    "Claiming that a Git SHA is a cryptographic author signature.",
    "Changing a pre-existing tag to force it onto a requested commit."
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "criterion": "Every generated VersionPlan, PublishPlan, tag report, and publish report includes the full resolved source commit SHA. The SHA is resolved from Git at planning time and is never inferred from a branch name during execution.",
      "is_error_case": false
    },
    {
      "id": "AC-002",
      "criterion": "Before any apply, tag, or publish mutation, execution resolves HEAD and requires it to equal the plan source_commit. A detached HEAD is permitted when it matches; a branch name, shallow symbolic reference, or changed worktree cannot substitute for equality. Mismatch fails before mutation with both SHAs in the diagnostic.",
      "is_error_case": true
