export const meta = {
  name: 'codex-track-a-implement-v2',
  description: 'Implement SPEC-004/005/006 (supply chain, doc authority, lane policy) v2 specs via canon/vector gates + TDD implementation',
  phases: [
    { title: 'Gate' },
    { title: 'Plan' },
    { title: 'Implement' },
    { title: 'Verify' },
  ],
}

const SPECS = [
  { id: '004-supply-chain-v2', path: '.claude/specs/SPEC-SUPPLY-CHAIN-REPRODUCIBILITY-004.json', branch: 'codex/004-supply-chain', effort: 'medium' },
  { id: '005-doc-authority-v2', path: '.claude/specs/SPEC-DOCUMENTATION-AUTHORITY-005.json', branch: 'codex/005-doc-authority', effort: 'medium' },
  { id: '006-lane-policy-v2', path: '.claude/specs/SPEC-RELEASE-LANE-POLICY-006.json', branch: 'codex/006-lane-policy', effort: 'medium' },
]

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    verdict: { type: 'string', enum: ['pass', 'fail'] },
    blockers: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
  required: ['verdict'],
}

const PLAN_SCHEMA = {
  type: 'object',
  properties: {
    tasks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          task_id: { type: 'string' },
          description: { type: 'string' },
          covers_criteria: { type: 'array', items: { type: 'string' } },
        },
        required: ['task_id', 'description'],
      },
    },
  },
  required: ['tasks'],
}

const IMPL_SCHEMA = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['completed', 'partial', 'blocked'] },
    branch: { type: 'string' },
    worktree_path: { type: 'string' },
    commits: { type: 'array', items: { type: 'string' } },
    tests_pass: { type: 'boolean' },
    lint_clean: { type: 'boolean' },
    summary: { type: 'string' },
    blockers: { type: 'array', items: { type: 'string' } },
  },
  required: ['status', 'summary'],
}

async function runSpec(spec) {
  phase('Gate')
  const gate = await agent(
    `Read the spec@1 JSON file at ${spec.path} in the callisto repo (/Users/gabe/Projects/callisto) in full — this is a freshly revised version of the spec, re-verify from scratch. Run the canon exit-gate check on it: every acceptance criterion must be a testable proposition with no vague language, no TBDs, error cases covered with is_error_case:true, and scope narrow enough for one planning cycle. Return a verdict.`,
    { phase: 'Gate', label: `gate:${spec.id}`, agentType: 'canon:exit-gate', schema: VERDICT_SCHEMA, effort: spec.effort }
  )
  if (!gate || gate.verdict !== 'pass') {
    log(`${spec.id}: spec exit-gate FAILED, skipping implementation — ${gate ? (gate.blockers || []).join('; ') : 'agent error'}`)
    return { spec: spec.id, stage: 'gate', gate }
  }

  phase('Plan')
  const plan = await agent(
    `Read the spec@1 at ${spec.path} in /Users/gabe/Projects/callisto. Produce a plan@1: dependency-ordered implementation tasks, each with exact file paths, a failing test written before implementation, the minimal implementation, a verification command, and covers_criteria naming every acceptance criterion it addresses. Every criterion must appear in some task's covers_criteria. Also read the spec's optional implementation_notes field if present and use it to inform crate/tooling choices.`,
    { phase: 'Plan', label: `plan:${spec.id}`, agentType: 'vector:planner', schema: PLAN_SCHEMA, effort: spec.effort }
  )
  if (!plan || !plan.tasks || !plan.tasks.length) {
    log(`${spec.id}: planner produced no tasks, skipping`)
    return { spec: spec.id, stage: 'plan', plan }
  }

  const challenge = await agent(
    `Adversarially review this plan@1 against the spec@1 at ${spec.path} (/Users/gabe/Projects/callisto). Plan tasks: ${JSON.stringify(plan.tasks)}. Check for missing acceptance criteria coverage, wrong task order, over/under-specified steps, poor compilation batching, missing error-case handling, orphaned criteria, and interface incompleteness. Verdict pass only if no blocking issues.`,
    { phase: 'Plan', label: `challenge:${spec.id}`, agentType: 'vector:challenger', schema: VERDICT_SCHEMA, effort: spec.effort }
  )
  if (!challenge || challenge.verdict !== 'pass') {
    log(`${spec.id}: plan challenger FAILED, skipping implementation — ${challenge ? (challenge.blockers || []).join('; ') : 'agent error'}`)
    return { spec: spec.id, stage: 'challenge', plan, challenge }
  }

  phase('Implement')
  const impl = await agent(
    `You are implementing SPEC ${spec.id} in the callisto repo (/Users/gabe/Projects/callisto), a Rust monorepo release-automation tool (unsafe_code="forbid" everywhere, atomic file writes via callisto_model::atomic::atomic_write, CST-preserving manifest edits via toml_edit/serde_json). Follow /Users/gabe/Projects/callisto/CLAUDE.md and AGENTS.md conventions.

Spec file: ${spec.path} — read it in full first, including its optional implementation_notes field for crate/tooling guidance.
Approved implementation plan (dependency-ordered tasks): ${JSON.stringify(plan.tasks)}

Follow strict TDD discipline per task, in order: write the failing test first, confirm it fails (red), write the minimal implementation to pass, confirm green, commit with a descriptive message referencing the task, before moving to the next task. Do not batch unrelated tasks into one commit. After all tasks are implemented and committed, run 'just ci-fast' (or at minimum 'cargo test -p <affected crates>' and 'cargo clippy -p <affected crates> -- -D warnings' if ci-fast is too slow) and fix any failures before finishing. Create and work on a new branch named '${spec.branch}' for this work — do not touch main, do not push, do not open a PR; leave the branch with commits for human review. If any task's acceptance criterion contradicts actual system behavior you discover while implementing, stop that task, report it as a blocker in your final report, and continue with the remaining independent tasks rather than faking a pass. Report your final branch name, the list of commit messages, and whether tests/lint are clean.`,
    { phase: 'Implement', label: `impl:${spec.id}`, agentType: 'general-purpose', isolation: 'worktree', schema: IMPL_SCHEMA, effort: spec.effort }
  )

  phase('Verify')
  if (!impl || impl.status === 'blocked') {
    log(`${spec.id}: implementation blocked — ${impl ? (impl.blockers || []).join('; ') : 'agent error'}`)
    return { spec: spec.id, stage: 'implement', plan, challenge, impl }
  }

  const verify = await agent(
    `Adversarially verify the implementation of SPEC ${spec.id}. Spec file: ${spec.path}. Implementation branch: ${impl.branch || spec.branch}, worktree: ${impl.worktree_path || 'unknown'} in /Users/gabe/Projects/callisto. Read the spec and the current code on that branch/worktree from scratch — do not trust the implementer's own summary. For each acceptance criterion, confirm it is implemented and tested with real evidence (file:line). Run the test suite and lint yourself if the worktree is still available. Verdict fail on any missing criterion, missing test, regression, or sibling-function gap.`,
    { phase: 'Verify', label: `verify:${spec.id}`, agentType: 'lambda:exit-gate', schema: VERDICT_SCHEMA, effort: 'high' }
  )

  return { spec: spec.id, stage: 'done', plan, challenge, impl, verify }
}

const results = await parallel(SPECS.map(s => () => runSpec(s)))
return results.filter(Boolean)

