export const meta = {
  name: 'release-trust-implement-all',
  description: 'Gate, plan, and implement all 6 release-trust specs -- Track A (004/005/006) parallel, Track B (001->002->003) sequential',
  phases: [
    { title: 'Gate' },
    { title: 'Plan' },
    { title: 'Implement' },
    { title: 'Verify' },
  ],
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    verdict: { type: 'string', enum: ['pass', 'fail'] },
    blockers: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
  required: ['verdict'],
}

const PLAN_SCHEMA = {
  type: 'object',
  properties: {
    tasks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          task_id: { type: 'string' },
          description: { type: 'string' },
          covers_criteria: { type: 'array', items: { type: 'string' } },
        },
        required: ['task_id', 'description'],
      },
    },
  },
  required: ['tasks'],
}

const IMPL_SCHEMA = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['completed', 'partial', 'blocked'] },
    branch: { type: 'string' },
    worktree_path: { type: 'string' },
    commits: { type: 'array', items: { type: 'string' } },
    tests_pass: { type: 'boolean' },
    lint_clean: { type: 'boolean' },
    summary: { type: 'string' },
    blockers: { type: 'array', items: { type: 'string' } },
  },
  required: ['status', 'summary'],
}

async function runSpec(spec) {
  phase('Gate')
  const gate = await agent(
    `Read the spec@1 JSON file at ${spec.path} in the callisto repo (/Users/gabe/Projects/callisto) in full, including any status/owner_track/depends_on/implementation_notes fields. Run the canon exit-gate check on it: every acceptance criterion must be a testable proposition with no vague language, no TBDs, error cases covered with is_error_case:true, and scope narrow enough for one planning cycle. Return a verdict.`,
    { phase: 'Gate', label: `gate:${spec.id}`, agentType: 'canon:exit-gate', schema: VERDICT_SCHEMA, effort: spec.effort }
  )
  if (!gate || gate.verdict !== 'pass') {
    log(`${spec.id}: spec exit-gate FAILED -- ${gate ? (gate.blockers || []).join('; ') : 'agent error'}`)
    return { spec: spec.id, stage: 'gate', gate }
  }
  log(`${spec.id}: gate PASSED`)

  phase('Plan')
  const plan = await agent(
    `Read the spec@1 at ${spec.path} in /Users/gabe/Projects/callisto. Produce a plan@1: dependency-ordered implementation tasks, each with exact file paths, a failing test written before implementation, the minimal implementation, a verification command, and covers_criteria naming every acceptance criterion it addresses. Every criterion must appear in some task's covers_criteria. Read the spec's optional implementation_notes and depends_on fields -- if depends_on names another spec, read that spec's file too and its corresponding implementation (if any exists yet in the repo, e.g. on a branch named codex/<spec-id-slug> or already merged) to ground this plan against real code, not the pre-dependency state. For every task wrapping a fallible external call, include both a happy-path and an error-path test.`,
    { phase: 'Plan', label: `plan:${spec.id}`, agentType: 'vector:planner', schema: PLAN_SCHEMA, effort: spec.effort }
  )
  if (!plan || !plan.tasks || !plan.tasks.length) {
    log(`${spec.id}: planner produced no tasks`)
    return { spec: spec.id, stage: 'plan', gate, plan }
  }

  const challenge = await agent(
    `Adversarially review this plan@1 against the spec@1 at ${spec.path} (/Users/gabe/Projects/callisto). Plan tasks: ${JSON.stringify(plan.tasks)}. Check for missing acceptance criteria coverage, wrong task order, over/under-specified steps, poor compilation batching, missing error-case handling, orphaned criteria, and interface incompleteness. Verdict pass only if no blocking issues.`,
    { phase: 'Plan', label: `challenge:${spec.id}`, agentType: 'vector:challenger', schema: VERDICT_SCHEMA, effort: spec.effort }
  )
  if (!challenge || challenge.verdict !== 'pass') {
    log(`${spec.id}: plan challenger FAILED -- ${challenge ? (challenge.blockers || []).join('; ') : 'agent error'}`)
    return { spec: spec.id, stage: 'challenge', gate, plan, challenge }
  }
  log(`${spec.id}: plan PASSED challenge, ${plan.tasks.length} tasks`)

  phase('Implement')
  const impl = await agent(
    `You are implementing SPEC ${spec.id} in the callisto repo (/Users/gabe/Projects/callisto), a Rust monorepo release-automation tool (unsafe_code="forbid" everywhere, atomic file writes via callisto_model::atomic::atomic_write, CST-preserving manifest edits via toml_edit/serde_json). Follow /Users/gabe/Projects/callisto/CLAUDE.md and AGENTS.md conventions.

Spec file: ${spec.path} -- read it in full first, including implementation_notes and depends_on. ${spec.baseBranch ? `This spec depends on work already implemented on branch '${spec.baseBranch}' -- base your branch on it (git checkout -b ${spec.branch} ${spec.baseBranch}) rather than on main/current HEAD, so its code is present.` : `Create and work on a new branch named '${spec.branch}' based on the current branch.`}

Approved implementation plan (dependency-ordered tasks): ${JSON.stringify(plan.tasks)}

